#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────

# The Collector's one-sitting setup on the home server (stage 5 of the media
# dashboard spec). Run it on the home server itself:
#
#   ssh homeserver
#   curl -fsSL https://raw.githubusercontent.com/Yuyan-Li1/TRMNL-Dashboard/main/collector/setup.sh -o setup.sh
#   bash setup.sh
#
# It is safe to run again: values already saved are kept with Enter.

COLLECTOR_HOME="$HOME/trmnl-collector"
ENV_FILE="$COLLECTOR_HOME/.env"
REPO_DIR="${REPO_DIR:-$HOME/trmnl-dashboard}"
REPO_URL="https://github.com/Yuyan-Li1/TRMNL-Dashboard.git"
DAEMON_LABEL="dev.yuyanli.trmnl-collector"
DAEMON_PLIST="/Library/LaunchDaemons/$DAEMON_LABEL.plist"
# node:sqlite needs no flag from Node 22.13
NODE_MIN_MAJOR=22
NODE_MIN_MINOR=13

ok() { printf '  %s✓%s %s\n' "$GREEN" "$RESET" "$1"; }

# node_ok: whether the installed Node is new enough for node:sqlite.
node_ok() {
  command -v node >/dev/null 2>&1 || return 1
  local major minor
  major=$(node -p 'process.versions.node.split(".")[0]')
  minor=$(node -p 'process.versions.node.split(".")[1]')
  (( major > NODE_MIN_MAJOR || (major == NODE_MIN_MAJOR && minor >= NODE_MIN_MINOR) ))
}

# ask_env KEY "Prompt" [secret]: ask for a value and save it to the .env.
ask_env() {
  local key="$1" prompt="$2"
  while true; do
    if [[ "${3:-}" == secret ]]; then ask_secret "$key" "$prompt"; else ask "$key" "$prompt"; fi
    [[ -n "${!key}" ]] && break
    warn "$key cannot be empty."
  done
  write_env "$key" "${!key}"
}

run_wizard() {

TOTAL_STAGES=6

banner "TRMNL Collector setup"

# ── 1 ─────────────────────────────────────────────────────────────────────
stage "Node and pnpm"
say "The Collector is run by Node $NODE_MIN_MAJOR.$NODE_MIN_MINOR or later, which has SQLite built in."
if node_ok; then
  ok "Node $(node -v) is installed."
else
  say "Node is missing or too old. The official installer for the current LTS"
  say "line (24) works on this Intel Mac and needs your password."
  if confirm "Download and install Node 24 from nodejs.org now?"; then
    pkg=$(curl -fsSL https://nodejs.org/dist/latest-v24.x/SHASUMS256.txt | awk '/\.pkg$/ {print $2; exit}')
    curl -fL "https://nodejs.org/dist/latest-v24.x/$pkg" -o "/tmp/$pkg"
    sudo installer -pkg "/tmp/$pkg" -target /
    rm -f "/tmp/$pkg"
    hash -r
  else
    step "Install Node yourself (https://nodejs.org/en/download), then come back."
    pause "Press Enter once 'node -v' works in a new shell"
    hash -r
  fi
  if ! node_ok; then
    warn "Node $NODE_MIN_MAJOR.$NODE_MIN_MINOR or later is still not on the PATH. Fix that and run this again."
    exit 1
  fi
  ok "Node $(node -v) is installed."
fi
if command -v pnpm >/dev/null 2>&1; then
  ok "pnpm $(pnpm -v) is installed."
else
  say "pnpm is missing. Installing it with npm needs your password."
  sudo npm install -g pnpm
  hash -r
  ok "pnpm $(pnpm -v) is installed."
fi
pause

# ── 2 ─────────────────────────────────────────────────────────────────────
stage "Clone the repo and install dependencies"
if [[ -d "$REPO_DIR/.git" ]]; then
  ok "The repo is already at $REPO_DIR."
  note "The Collector pulls main itself every night; this run leaves the checkout as it is."
else
  say "Cloning $REPO_URL into $REPO_DIR."
  git clone "$REPO_URL" "$REPO_DIR"
fi
(cd "$REPO_DIR" && pnpm install --frozen-lockfile)
ok "Dependencies are installed."
pause

# ── 3 ─────────────────────────────────────────────────────────────────────
stage "The Collector's folder and its secrets"
mkdir -p "$COLLECTOR_HOME/logs"
chmod 700 "$COLLECTOR_HOME"
[[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
chmod 600 "$ENV_FILE"
ok "$COLLECTOR_HOME is readable only by you."
say "Five of these are the same values Vercel has: Vercel > the dashboard"
say "project > Settings > Environment Variables. Paste each one here."
ask_env UPSTASH_REDIS_REST_URL "UPSTASH_REDIS_REST_URL:"
ask_env UPSTASH_REDIS_REST_TOKEN "UPSTASH_REDIS_REST_TOKEN:" secret
ask_env TELEGRAM_BOT_TOKEN "TELEGRAM_BOT_TOKEN:" secret
ask_env TELEGRAM_CHAT_ID "TELEGRAM_CHAT_ID:"
ask_env CRON_SECRET "CRON_SECRET:" secret
step "The dashboard's address, with https:// (https://trmnl.yuyanli.dev)."
ask_env DASHBOARD_URL "DASHBOARD_URL:"
step "Your Goodreads user id: the number in your profile's address,"
step "goodreads.com/user/show/<number>-<name>. Digits only."
while true; do
  ask_env GOODREADS_USER_ID "GOODREADS_USER_ID:"
  [[ "$GOODREADS_USER_ID" =~ ^[0-9]+$ ]] && break
  warn "That is not a number. The widget only answers to the bare numeric id."
done
pause

# ── 4 ─────────────────────────────────────────────────────────────────────
stage "Claude Code and its token"
say "LLM picks arrive only in stage 8. This is done now because whether the"
say "Claude Code CLI works on this Intel Mac is the one untested fact stage 8"
say "rests on. If this stage fails, the rest of the setup still goes ahead."
export PATH="$HOME/.local/bin:$PATH"
if ! command -v claude >/dev/null 2>&1; then
  if confirm "Install the Claude Code CLI with Anthropic's installer (claude.ai/install.sh)?"; then
    curl -fsSL https://claude.ai/install.sh | bash || warn "The installer failed."
    hash -r
  fi
fi
if command -v claude >/dev/null 2>&1; then
  ok "Claude Code $(claude --version 2>/dev/null || echo '(version unknown)') is installed."
  if grep -q '^ANTHROPIC_API_KEY=' "$ENV_FILE" || [[ -n "${ANTHROPIC_API_KEY:-}" ]]; then
    warn "ANTHROPIC_API_KEY is set here or in $ENV_FILE. Remove it: it would be"
    warn "used in place of the subscription token."
  fi
  if [[ -z "$(_existing CLAUDE_CODE_OAUTH_TOKEN || true)" ]] || confirm "A token is already saved. Make a new one?"; then
    step "'claude setup-token' runs next. Sign in with the link it prints, then"
    step "copy the token it shows at the end (it starts sk-ant-oat)."
    pause
    claude setup-token || warn "'claude setup-token' did not finish."
  fi
  ask_secret CLAUDE_CODE_OAUTH_TOKEN "Paste the token (Enter with nothing to skip):"
  if [[ -n "$CLAUDE_CODE_OAUTH_TOKEN" ]]; then
    write_env CLAUDE_CODE_OAUTH_TOKEN "$CLAUDE_CODE_OAUTH_TOKEN"
    say "Asking Claude one trivial question with that token..."
    if (cd "$COLLECTOR_HOME" && env -u ANTHROPIC_API_KEY CLAUDE_CODE_OAUTH_TOKEN="$CLAUDE_CODE_OAUTH_TOKEN" \
        claude -p "Reply with the single word: ok"); then
      ok "'claude -p' works on this Mac."
    else
      SKIPPED+=("'claude -p' failed on this Mac: stage 8 (LLM picks) has to be reconsidered")
      warn "'claude -p' failed. Carrying on; stage 8 is reconsidered."
    fi
  else
    SKIPPED+=("CLAUDE_CODE_OAUTH_TOKEN (run 'claude setup-token' and add it to $ENV_FILE)")
  fi
else
  SKIPPED+=("Claude Code CLI is not installed: stage 8 (LLM picks) has to be reconsidered")
  warn "Claude Code is not installed. Carrying on; stage 8 is reconsidered."
fi
pause

# ── 5 ─────────────────────────────────────────────────────────────────────
stage "The launchd job"
say "launchd starts 'collector tick' every 15 minutes as you ($USER), from"
say "boot, with nobody logged in. Installing it needs your password."
wrapper="$COLLECTOR_HOME/collector"
cat > "$wrapper" <<WRAPPER
#!/bin/sh
# Written by collector/setup.sh. Runs the Collector from the repo.
export HOME="$HOME"
export PATH="$(dirname "$(command -v node)"):$(dirname "$(command -v pnpm)"):$(dirname "$(command -v git)"):$HOME/.local/bin:/usr/local/bin:/usr/bin:/bin"
cd "$REPO_DIR" || exit 1
exec node_modules/.bin/tsx collector/cli.ts "\$@"
WRAPPER
chmod 700 "$wrapper"
ok "Wrote $wrapper."
say "One tick by hand first, so any mistake shows here and not in a log:"
if "$wrapper" tick; then
  ok "The tick ran."
else
  warn "The tick failed. Fix what it says above and run this wizard again."
  exit 1
fi
plist=$(mktemp)
cat > "$plist" <<PLIST
<?xml version="1.0" encoding="UTF-8"?>
<!DOCTYPE plist PUBLIC "-//Apple//DTD PLIST 1.0//EN" "http://www.apple.com/DTDs/PropertyList-1.0.dtd">
<plist version="1.0">
<dict>
	<key>Label</key>
	<string>$DAEMON_LABEL</string>
	<key>UserName</key>
	<string>$USER</string>
	<key>ProgramArguments</key>
	<array>
		<string>$wrapper</string>
		<string>tick</string>
	</array>
	<key>StartInterval</key>
	<integer>900</integer>
	<key>RunAtLoad</key>
	<true/>
	<key>StandardOutPath</key>
	<string>$COLLECTOR_HOME/logs/tick.log</string>
	<key>StandardErrorPath</key>
	<string>$COLLECTOR_HOME/logs/tick.log</string>
</dict>
</plist>
PLIST
if confirm "Install $DAEMON_PLIST and start it?"; then
  sudo launchctl bootout "system/$DAEMON_LABEL" 2>/dev/null || true
  sudo install -m 644 -o root -g wheel "$plist" "$DAEMON_PLIST"
  sudo launchctl bootstrap system "$DAEMON_PLIST"
  ok "The job is installed. Its log is $COLLECTOR_HOME/logs/tick.log."
else
  SKIPPED+=("the launchd job ($DAEMON_PLIST): run this wizard again to install it")
fi
rm -f "$plist"
pause

# ── 6 ─────────────────────────────────────────────────────────────────────
stage "A test Alert"
say "Sending a test Alert to Telegram with 'collector test-alert'."
if "$wrapper" test-alert; then
  step "Check Telegram: '[home] Test Alert from the Collector.' should be there."
else
  SKIPPED+=("the test Alert: check TELEGRAM_BOT_TOKEN and TELEGRAM_CHAT_ID in $ENV_FILE")
fi
note "Run the Collector by hand with: $wrapper <command>"
pause

finish
}

run_wizard "$@"; exit
